#include <stdio.h>

/* teste do desafio zeros-garantidos — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario captura o stdout no proprio teste: o freopen manda o stdout
   para um arquivo temporario POR CENARIO, o teste chama a funcao do aluno e
   le o arquivo de volta. Nunca ha fclose de stdout — so fflush — para o
   segundo freopen ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void zerosGarantidos(int a, int b);

SM_TEST(sete_tres_e_tres_zeros) {
    freopen("sm_saida_1.tmp", "w", stdout);
    zerosGarantidos(7, 3);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a gaveta 0", linha, "7\n",
              "o primeiro valor entre as chaves foi para a gaveta 0");
    fgets(linha, 80, f);
    checa_str("a gaveta 1", linha, "3\n",
              "o segundo valor entre as chaves foi para a gaveta 1");
    fgets(linha, 80, f);
    checa_str("a gaveta 2", linha, "0\n",
              "a gaveta 2 ficou fora do inicializador: nasceu em zero");
    fgets(linha, 80, f);
    checa_str("a gaveta 3", linha, "0\n",
              "a gaveta 3 tambem ficou de fora, e tambem nasceu em zero");
    fgets(linha, 80, f);
    checa_str("a gaveta 4", linha, "0\n",
              "a gaveta 4 fecha as cinco: zero, como as outras de tras");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na quinta gaveta: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(outros_dois_valores) {
    freopen("sm_saida_2.tmp", "w", stdout);
    zerosGarantidos(40, 5);
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a gaveta 0 com outro valor", linha, "40\n",
              "as duas primeiras gavetas vem dos valores recebidos, nao do codigo");
    fgets(linha, 80, f);
    checa_str("a gaveta 1 com outro valor", linha, "5\n",
              "o segundo valor recebido entra na gaveta 1");
    fgets(linha, 80, f);
    checa_str("a gaveta 2 continua zero", linha, "0\n",
              "trocar os valores nao muda o resto: as gavetas de tras nascem em zero");
    fclose(f);
}

